<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRoute } from "vue-router";
import { MessageCircle, Send, Search, CircleHelp } from "lucide-vue-next";
import SiteHeader from "../components/SiteHeader.vue";
import SiteFooter from "../components/SiteFooter.vue";
import { communicationApi, type Conversation, type ChatMessage } from "../services/communication";

interface Message { id: string; text: string; sent: boolean; time: string; read?:boolean; attachmentUrl?:string; productId?:string; orderId?:string }
interface ChatView { id: string; seller: string; last: string; messages: Message[]; online: boolean; typing: string | null }
const route = useRoute();
const conversations = ref<ChatView[]>(JSON.parse(localStorage.getItem("bx-chats") ?? "null") as ChatView[] ?? [
  { id:"demo-tech", seller: "TechStore Official", last: "Thanks for reaching out. How can we help?", online:true, typing:null, messages: [{ id: "m1", text: "Hi, is this item available?", sent: true, time: "10:20 AM" }, { id: "m2", text: "Thanks for reaching out. How can we help?", sent: false, time: "10:23 AM" }] },
  { id:"demo-style", seller: "StyleHub", last: "We can help with sizing details.", online:false, typing:null, messages: [{ id: "m3", text: "We can help with sizing details.", sent: false, time: "Yesterday" }] },
  { id:"demo-grocery", seller: "GroceryMart", last: "Your question was received.", online:false, typing:null, messages: [{ id: "m4", text: "Your question was received.", sent: false, time: "Mon" }] },
]);
const selectedSeller = ref(String(route.params.seller ?? conversations.value[0]?.seller ?? ""));
const message = ref("");
const attachmentUrl = ref("");
const productId = ref("");
const orderId = ref("");
const search = ref("");
const loading = ref(false); const error = ref("");
const current = computed(() => conversations.value.find((item) => item.seller === selectedSeller.value));
const filtered = computed(() => conversations.value.filter((item) => item.seller.toLowerCase().includes(search.value.toLowerCase())));
let refreshTimer: number | undefined;
function mapMessage(message: ChatMessage): Message { return { id:message.id,text:message.text,sent:message.sender === "buyer",time:new Date(message.sentAt).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"}),read:message.read,attachmentUrl:message.attachmentUrl,productId:message.productId,orderId:message.orderId }; }
function mapConversation(item: Conversation): ChatView { return { id:item.id,seller:item.seller,last:item.lastMessage,messages:item.messages.map(mapMessage),online:item.online,typing:item.typing }; }
async function load() { loading.value = true; error.value = ""; try { if (communicationApi.enabled) { let result = await communicationApi.conversations(); const routeSeller = String(route.params.seller ?? ""); if (routeSeller && !result.data.some((item)=>item.seller === routeSeller)) { await communicationApi.start(routeSeller); result = await communicationApi.conversations(); } conversations.value = result.data.map(mapConversation); } if (!selectedSeller.value || !conversations.value.some((item)=>item.seller === selectedSeller.value)) selectedSeller.value = String(route.params.seller ?? conversations.value[0]?.seller ?? ""); if (current.value && communicationApi.enabled && !current.value.id.startsWith("demo-")) await communicationApi.markRead(current.value.id); } catch (cause) { error.value = cause instanceof Error ? cause.message : "Messages could not be loaded."; } finally { loading.value = false; } }
onMounted(() => { void load(); refreshTimer = window.setInterval(() => { void load(); }, 5000); });
onBeforeUnmount(() => { if (refreshTimer) window.clearInterval(refreshTimer); });
watch(() => route.params.seller, (value) => { if (value && conversations.value.some((item) => item.seller === value)) selectedSeller.value = String(value); });
async function select(item: ChatView) { selectedSeller.value = item.seller; if(communicationApi.enabled && !item.id.startsWith("demo-")) { try { await communicationApi.markRead(item.id); } catch { error.value="Read status could not be updated."; } } }
let typingTimer: number | undefined;
function updateTyping() { if (!current.value || !communicationApi.enabled || current.value.id.startsWith("demo-")) return; void communicationApi.typing(current.value.id, true); if (typingTimer) window.clearTimeout(typingTimer); typingTimer = window.setTimeout(() => { if (current.value) void communicationApi.typing(current.value.id, false); }, 900); }
async function send() { const text = message.value.trim(); if ((!text && !attachmentUrl.value.trim()) || !current.value) return; try { if (communicationApi.enabled && !current.value.id.startsWith("demo-")) { const saved = await communicationApi.send(current.value.id,text,{attachmentUrl:attachmentUrl.value.trim()||undefined,productId:productId.value.trim()||undefined,orderId:orderId.value.trim()||undefined}); current.value.messages.push(mapMessage(saved)); } else { current.value.messages.push({ id: `m-${Date.now()}`, text, sent: true, time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),attachmentUrl:attachmentUrl.value.trim()||undefined,productId:productId.value.trim()||undefined,orderId:orderId.value.trim()||undefined }); localStorage.setItem("bx-chats", JSON.stringify(conversations.value)); } current.value.last = text || "Attachment"; message.value = ""; attachmentUrl.value="";productId.value="";orderId.value="";error.value = ""; } catch (cause) { error.value = cause instanceof Error ? cause.message : "Message could not be sent."; } }
</script>

<template><div class="page-shell"><SiteHeader /><main class="container content-page"><div class="breadcrumb"><RouterLink to="/">Home</RouterLink><span>/</span><span>Buyer–Seller chat</span></div><div class="chat-title"><span class="eyebrow">MESSAGES</span><h1>Buyer–Seller chat</h1><p>Ask stores about products and orders before you buy.</p></div><section class="chat-window"><p v-if="loading" class="chat-state" role="status">Loading your conversations…</p><p v-if="error" class="chat-error" role="alert">{{ error }}</p><aside class="chat-list"><h2>Conversations</h2><label><Search /><input v-model="search" aria-label="Search conversations" placeholder="Search stores" /></label><button v-for="item in filtered" :key="item.seller" :class="{ selected: selectedSeller === item.seller }" @click="select(item)"><span class="store-avatar">{{ item.seller.charAt(0) }}</span><span><b>{{ item.seller }} <i v-if="item.messages.some(message=>!message.read && !message.sent)">New</i></b><small>{{ item.last }}</small></span></button><p v-if="!filtered.length" class="chat-empty-list">No conversations found.</p></aside><section v-if="current" class="chat-body"><header><span class="store-avatar">{{ current.seller.charAt(0) }}</span><div><b>{{ current.seller }}</b><small>{{ current.typing ? 'Typing…' : current.online ? 'Online' : 'Marketplace seller' }}</small></div></header><div class="message-history"><p class="chat-safety"><CircleHelp /> Keep payment on BazaarX for purchase protection.</p><article v-for="item in current.messages" :key="item.id" :class="{ mine: item.sent }"><a v-if="item.attachmentUrl" :href="item.attachmentUrl" target="_blank" rel="noreferrer"><img :src="item.attachmentUrl" alt="Chat attachment" /></a><span>{{ item.productId ? `Product: ${item.productId} · ` : '' }}{{ item.orderId ? `Order: ${item.orderId} · ` : '' }}{{ item.text }}</span><small>{{ item.time }}{{ item.sent ? item.read ? ' · Read' : ' · Sent' : '' }}</small></article></div><form @submit.prevent="send"><input v-model="message" aria-label="Type your message" placeholder="Type a message..." @input="updateTyping" /><button :disabled="!message.trim() && !attachmentUrl.trim()" aria-label="Send message"><Send /></button></form><div class="chat-context"><input v-model="attachmentUrl" aria-label="Image URL" placeholder="Image URL (optional)" /><input v-model="productId" aria-label="Product reference" placeholder="Product ID (optional)" /><input v-model="orderId" aria-label="Order reference" placeholder="Order ID (optional)" /></div></section><section v-else class="chat-no-selection"><MessageCircle /><b>Choose a conversation</b><p>Select a seller to read and send messages.</p></section></section></main><SiteFooter /></div></template>

<style scoped>
