body>header small{font-size:10px;color:#178451}.message-history{background:#fafbfd;padding:14px 18px;overflow:auto;display:flex;flex-direction:column;gap:12px}.chat-safety{align-self:center;border:1px solid #f0e4c7;background:#fff9e9;color:#8b7441;border-radius:20px;padding:8px 11px;font-size:10px;display:flex;align-items:center;gap:5px}.chat-safety svg{width:13px}.message-history article{display:flex;flex-direction:column;align-items:flex-start;max-width:75%;gap:4px}.message-history article span{background:white;border:1px solid #ebeff3;padding:10px 12px;border-radius:12px 12px 12px 3px;font-size:12px;color:#34445a}.message-history article small{font-size:9px;color:#96a0ae}.message-history article.mine{align-self:flex-end;align-items:flex-end}.message-history article.mine span{background:#2463ce;color:white;border-color:#2463ce;border-radius:12px 12px 3px 12px}.chat-body form{display:flex;gap:9px;align-items:center;padding:10px 14px;border-top:1px solid #edf0f4}.chat-body form input{flex:1;min-width:0;border:1px solid #e0e6ed;border-radius:9px;padding:11px;font:inherit;font-size:12px}.chat-body form button{width:39px;height:39px;border:0;border-radius:9px;color:white;background:#f4511e;display:grid;place-items:center;cursor:pointer}.chat-body form button:disabled{opacity:.5}.chat-body form svg{width:17px}.chat-no-selection{display:grid;place-content:center;justify-items:center;color:#75849a}.chat-no-selection svg{color:#f4511e}.chat-no-selection b{color:#203149;margin-top:10px}.chat-no-selection p,.chat-empty-list{font-size:12px}@media(max-width:700px){.chat-window{grid-template-columns:115px 1fr;height:490px}.chat-list{padding:9px}.chat-list>label{padding:7px}.chat-list>button{justify-content:center;padding:10px 0}.chat-list>button>span:last-child{display:none}.chat-list h2{font-size:13px}.chat-body>header{padding:0 10px}.message-history{padding:10px}.message-history article{max-width:90%}}
</style>
